"""Dependency-free educational logistic regression and evaluation.

Not a credit-bureau model; intentionally transparent, small-batch reference code.
"""
import math

FEATURES = ['history_months','accounts_count','utilization','debt_service_ratio',
            'max_dpd_12m','late_share_12m','payment_ratio_12m','inquiries_6m']

def sigmoid(x):
    return 1 / (1 + math.exp(-max(-35, min(35, x))))

def fit(rows, epochs=350, learning_rate=0.09, l2=0.015):
    n, d = len(rows), len(FEATURES)
    means = [sum(r[f] for r in rows)/n for f in FEATURES]
    scales = [(sum((r[f]-means[j])**2 for r in rows)/n)**0.5 or 1
              for j,f in enumerate(FEATURES)]
    x = [[(r[f]-means[j])/scales[j] for j,f in enumerate(FEATURES)] for r in rows]
    y = [r['bad_6m'] for r in rows]
    prevalence = min(.999,max(.001,sum(y)/n))
    bias = math.log(prevalence/(1-prevalence))
    weights = [0.0]*d
    for _ in range(epochs):
        gradient, gb = [0.0]*d, 0.0
        for xi,yi in zip(x,y):
            error = sigmoid(bias+sum(w*v for w,v in zip(weights,xi)))-yi
            gb += error
            for j in range(d):
                gradient[j] += error*xi[j]
        weights = [w-learning_rate*(g/n+l2*w) for w,g in zip(weights,gradient)]
        bias -= learning_rate*gb/n
    return dict(features=FEATURES,means=means,scales=scales,weights=weights,
                intercept=bias,epochs=epochs,learning_rate=learning_rate,l2=l2)

def predict(model,row):
    z = model['intercept']+sum(w*(row[f]-m)/s for f,w,m,s in
         zip(model['features'],model['weights'],model['means'],model['scales']))
    return sigmoid(z)

def auc(y,p):
    positives,negatives = sum(y),len(y)-sum(y)
    if not positives or not negatives:
        return None
    groups = {}
    for yi,pi in zip(y,p):
        counts=groups.setdefault(pi,[0,0]);counts[yi]+=1
    below,total=0,0.0
    for pi,(neg,pos) in sorted(groups.items()):
        total += pos*(below+neg*.5);below += neg
    return total/(positives*negatives)

def average_precision(y,p):
    if not sum(y):
        return None
    groups={}
    for yi,pi in zip(y,p):
        counts=groups.setdefault(pi,[0,0]);counts[yi]+=1
    tp,fp,result=0,0,0.0
    for pi,(neg,pos) in sorted(groups.items(),reverse=True):
        tp+=pos;fp+=neg;result+=(pos/sum(y))*(tp/(tp+fp))
    return result

def confusion(y,p,threshold):
    tp=sum(yi==1 and pi>=threshold for yi,pi in zip(y,p))
    fp=sum(yi==0 and pi>=threshold for yi,pi in zip(y,p))
    fn=sum(yi==1 and pi<threshold for yi,pi in zip(y,p))
    tn=len(y)-tp-fp-fn
    precision=tp/(tp+fp) if tp+fp else 0
    recall=tp/(tp+fn) if tp+fn else 0
    return dict(tp=tp,fp=fp,fn=fn,tn=tn,precision=precision,recall=recall,
                f1=2*precision*recall/(precision+recall) if precision+recall else 0)

def evaluate(y,p,threshold):
    return dict(n=len(y),events=sum(y),prevalence=sum(y)/len(y),roc_auc=auc(y,p),
       average_precision=average_precision(y,p),
       brier=sum((pi-yi)**2 for yi,pi in zip(y,p))/len(y),
       log_loss=-sum(yi*math.log(max(1e-12,pi))+(1-yi)*math.log(max(1e-12,1-pi))
                     for yi,pi in zip(y,p))/len(y),
       threshold=threshold,**confusion(y,p,threshold))
